/* Demonstrates setting a mutex attribute to PTHREAD_PROCESS_SHARED */
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <errno.h>

#define HANDLE_ERROR(msg) \
    do { fprintf(stderr, "Error: %s\n", msg); return EXIT_FAILURE; } while (0)

int main(void) {
    pthread_mutexattr_t attr;
    int pshared_value;
    int s;

    /* 1. Initialize the attributes object */
    s = pthread_mutexattr_init(&attr);
    if (s != 0) {
        HANDLE_ERROR("pthread_mutexattr_init");
    }

    /* 2. Set the process-shared attribute to allow cross-process use */
    s = pthread_mutexattr_setpshared(&attr, PTHREAD_PROCESS_SHARED);
    if (s != 0) {
        pthread_mutexattr_destroy(&attr);
        HANDLE_ERROR("pthread_mutexattr_setpshared");
    }

    /* 3. Verify the setting using pthread_mutexattr_getpshared */
    s = pthread_mutexattr_getpshared(&attr, &pshared_value);
    if (s != 0) {
        pthread_mutexattr_destroy(&attr);
        HANDLE_ERROR("pthread_mutexattr_getpshared");
    }

    if (pshared_value == PTHREAD_PROCESS_SHARED) {
        printf("Mutex attributes successfully set for process sharing (PTHREAD_PROCESS_SHARED).\n");
    } else {
        printf("Error: Mutex attributes unexpectedly set to PRIVATE.\n");
    }

    /* 4. Clean up the attributes object */
    s = pthread_mutexattr_destroy(&attr);
    if (s != 0) {
        HANDLE_ERROR("pthread_mutexattr_destroy");
    }

    return EXIT_SUCCESS;
}
